B.bVG=new A.hT(B.FI,"Smart Back Navigation & Zero Accidental Exits","Pressing back from your Profile, Receipts, or Membership smoothly returns to your Home dashboard. Explicit back buttons added across all pages with double-tap exit protection.","Seamless Nav","navigation",null,null)
